{"status":"partial","summary":"Implementado o núcleo funcional do PC Service em React: dashboard derivado dos registros, cadastro/edição/pesquisa de clientes, criação e consulta de ordens, filtros combináveis, orçamento em centavos, aprovação, transições de status e histórico persistido. Direção de design: assistência técnica operacional para pequenas equipes; workspace dark-tech com navegação lateral, listas de trabalho densas, tipografia de interface legível, azul elétrico como ação e pontos luminosos para status. A persistência disponível neste ambiente é local e não equivale ao banco de dados de servidor solicitado.","files":[{"path":"src/App.tsx","content":"import React, { useEffect, useMemo, useState } from 'react';
import './styles.css';

type Status = 'Recebido'|'Em diagnóstico'|'Aguardando aprovação'|'Em manutenção'|'Pronto'|'Entregue'|'Cancelado';
type Client={id:string;name:string;phone:string;email:string;notes:string};
type Item={id:string;description:string;type:'Peça'|'Serviço';qty:number;unit:number};
type Log={date:string;from:string;to:string};
type Order={id:string;number:string;clientId:string;equipment:string;brand:string;model:string;problem:string;diagnosis:string;entered:string;due:string;status:Status;items:Item[];discount:number;approvedAt?:string;history:Log[]};
type DB={clients:Client[];orders:Order[];next:number};
const key='pcservice-v1'; const now=()=>new Date().toISOString(); const date=(n=0)=>{const d=new Date();d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const money=(v:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);
const steps:Status[]=['Recebido','Em diagnóstico','Aguardando aprovação','Em manutenção','Pronto','Entregue'];
function seed():DB { const clients=[['Ana Souza','11987654321'],['Bruno Lima','11976543210'],['Carla Mendes','11965432109'],['Diego Alves','11954321098'],['Elisa Rocha','11943210987']].map((x,i)=>({id:'c'+(i+1),name:x[0],phone:x[1],email:i===0?'ana@email.com':'',notes:''})); const mk=(i:number,s:Status,due:number):Order=>({id:'o'+i,number:'OS-2025-'+String(1000+i),clientId:clients[i%5].id,equipment:i%2?'Notebook':'Desktop',brand:'Dell',model:'Inspiron '+(3000+i),problem:'Avaliação técnica e manutenção preventiva.',diagnosis:'',entered:date(-i),due:date(due),status:s,items:[{id:'i'+i,description:'Diagnóstico técnico',type:'Serviço',qty:1,unit:9000}],discount:0,approvedAt:s==='Em manutenção'||s==='Pronto'||s==='Entregue'?now():undefined,history:[{date:now(),from:'',to:s}]}); return {clients,orders:[mk(1,'Recebido',2),mk(2,'Em diagnóstico',-2),mk(3,'Aguardando aprovação',4),mk(4,'Em manutenção',3),mk(5,'Pronto',-1),mk(6,'Entregue',-4),mk(7,'Cancelado',1),mk(8,'Recebido',5)],next:1009}; }
function load(){try{const x=localStorage.getItem(key);return x?JSON.parse(x):seed()}catch{return seed()}}
export default function App(){
 const [db,setDb]=useState<DB>(load); const [page,setPage]=useState<'dash'|'clients'|'orders'>('dash'); const [selected,setSelected]=useState<string|null>(null); const [clientForm,setClientForm]=useState<Client|null>(null); const [orderForm,setOrderForm]=useState(false); const [query,setQuery]=useState(''); const [status,setStatus]=useState(''); const [late,setLate]=useState(false); const [notice,setNotice]=useState(''); const [error,setError]=useState('');
 useEffect(()=>{try{localStorage.setItem(key,JSON.stringify(db))}catch{setError('Não foi possível gravar os dados neste navegador.')}},[db]);
 const save=(fn:(d:DB)=>DB)=>{setError('');setDb(d=>fn(d));}; const client=(id:string)=>db.clients.find(x=>x.id===id);
 const total=(o:Order)=>o.items.reduce((a,i)=>a+i.qty*i.unit,0)-o.discount;
 const metrics=useMemo(()=>{const open=db.orders.filter(o=>!['Entregue','Cancelado'].includes(o.status));return {open:open.length,ready:db.orders.filter(o=>o.status==='Pronto').length,late:open.filter(o=>o.due<date()).length,value:open.reduce((a,o)=>a+total(o),0)}},[db]);
 const filtered=db.orders.filter(o=>{const c=client(o.clientId);return (!query||o.number.toLowerCase().includes(query.toLowerCase())||c?.name.toLowerCase().includes(query.toLowerCase()))&&(!status||o.status===status)&&(!late||(!['Entregue','Cancelado'].includes(o.status)&&o.due<date()))});
 function saveClient(){if(!clientForm)return; if(!clientForm.name.trim()||!clientForm.phone.trim())return setError('Nome e telefone são obrigatórios.');if(clientForm.email&&!/^\S+@\S+\.\S+$/.test(clientForm.email))return setError('Informe um e-mail válido.');save(d=>({...d,clients:d.clients.some(c=>c.id===clientForm.id)?d.clients.map(c=>c.id===clientForm.id?clientForm:c):[...d.clients,clientForm]}));setClientForm(null);setNotice('Cliente gravado com sucesso.');}
 function createOrder(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);if(!f.get('client')||!f.get('problem'))return setError('Cliente e problema relatado são obrigatórios.');const id=String(db.next);const o:Order={id:'o'+id,number:'OS-2025-'+id,clientId:String(f.get('client')),equipment:String(f.get('equipment')),brand:String(f.get('brand')),model:String(f.get('model')),problem:String(f.get('problem')),diagnosis:'',entered:date(),due:String(f.get('due')),status:'Recebido',items:[],discount:0,history:[{date:now(),from:'',to:'Recebido'}]};save(d=>({...d,next:d.next+1,orders:[o,...d.orders]}));setOrderForm(false);setSelected(o.id);setNotice('Ordem criada e gravada.');}
 const nav=(p:any)=>{setPage(p);setSelected(null);setError('');};
 return <div className="shell"><aside><div className="logo"><b>PC</b> Service</div><nav>{[['dash','▦','Dashboard'],['clients','◉','Clientes'],['orders','≡','Ordens de serviço']].map(([p,i,l])=><button key={p} className={page===p?'active':''} onClick={()=>nav(p)}>{i}<span>{l}</span></button>)}</nav><small>Empresa demonstração<br/>Dados locais deste navegador</small></aside><main>{notice&&<div className="notice">✓ {notice}<button onClick={()=>setNotice('')}>×</button></div>}{error&&<div className="error">{error}<button onClick={()=>setError('')}>×</button></div>}
 {page==='dash'&&<Dashboard metrics={metrics} orders={db.orders.slice().sort((a,b)=>b.entered.localeCompare(a.entered)).slice(0,5)} client={client} total={total} open={(id)=>{setPage('orders');setSelected(id)}}/>}
 {page==='clients'&&<Clients clients={db.clients} orders={db.orders} selected={selected} setSelected={setSelected} form={clientForm} setForm={setClientForm} save={saveClient} error={setError} />}
 {page==='orders'&&<Orders orders={filtered} all={db.orders} clients={db.clients} selected={selected} setSelected={setSelected} query={query} setQuery={setQuery} status={status} setStatus={setStatus} late={late} setLate={setLate} clear={()=>{setQuery('');setStatus('');setLate(false)}} create={()=>setOrderForm(true)} save={save} total={total} error={setError} notice={setNotice}/>} 
 </main>{orderForm&&<OrderCreate clients={db.clients} close={()=>setOrderForm(false)} submit={createOrder}/>}</div>
}
function Dashboard({metrics,orders,client,total,open}:any){return <><header><div><p>VISÃO GERAL</p><h1>Oficina em movimento</h1></div></header><section className="metrics"><Metric n={metrics.open} l="Ordens abertas"/><Metric n={metrics.ready} l="Prontas para retirada"/><Metric n={metrics.late} l="Ordens atrasadas" bad/><Metric n={money(metrics.value)} l="Orçamentos em aberto"/></section><section className="panel"><div className="sectionhead"><h2>Ordens recentes</h2><span>Últimas 5 entradas</span></div><OrderTable orders={orders} client={client} total={total} open={open}/></section></>}; function Metric({n,l,bad}:any){return <div className="metric"><strong className={bad?'bad':''}>{n}</strong><span>{l}</span></div>}
function Clients({clients,orders,selected,setSelected,form,setForm,save,error}:any){const [q,setQ]=useState('');const visible=clients.filter((c:Client)=>c.name.toLowerCase().includes(q.toLowerCase())||c.phone.includes(q));const c=clients.find((x:Client)=>x.id===selected);return <><header><div><p>CADASTRO</p><h1>Clientes</h1></div><button data-testid="btn-new-client" className="primary" onClick={()=>setForm({id:'c'+Date.now(),name:'',phone:'',email:'',notes:''})}>+ Novo cliente</button></header><div className="split"><section className="panel list"><input data-testid="client-search" placeholder="Buscar por nome ou telefone" value={q} onChange={e=>setQ(e.target.value)}/>{visible.length?visible.map((x:Client)=><button className={'row '+(selected===x.id?'selected':'')} key={x.id} onClick={()=>setSelected(x.id)}><b>{x.name}</b><span>{x.phone}</span></button>):<div className="empty">Nenhum cliente encontrado.</div>}</section><section className="panel detail">{c?<><div className="sectionhead"><h2>{c.name}</h2><button className="secondary" onClick={()=>setForm(c)}>Editar</button></div><p>{c.phone} {c.email&&' · '+c.email}</p><p className="muted">{c.notes||'Sem observações.'}</p><h3>Ordens vinculadas</h3>{orders.filter((o:Order)=>o.clientId===c.id).map((o:Order)=><div className="linked" key={o.id}>{o.number}<Badge s={o.status}/></div>)}<button className="danger" onClick={()=>orders.some((o:Order)=>o.clientId===c.id)?error('Este cliente não pode ser excluído porque possui ordens vinculadas.'):null}>Excluir cliente</button></>:<div className="empty">Selecione um cliente para ver seus dados.</div>}</section></div>{form&&<ClientModal form={form} set={setForm} save={save}/>}</>}
function ClientModal({form,set,save}:any){return <div className="modal"><form className="dialog" onSubmit={e=>{e.preventDefault();save()}}><h2>{form.name?'Editar cliente':'Novo cliente'}</h2><label>Nome*<input data-testid="client-name" value={form.name} onChange={e=>set({...form,name:e.target.value})}/></label><label>Telefone*<input data-testid="client-phone" value={form.phone} onChange={e=>set({...form,phone:e.target.value})}/></label><label>E-mail<input data-testid="client-email" value={form.email} onChange={e=>set({...form,email:e.target.value})}/></label><label>Observações<textarea value={form.notes} onChange={e=>set({...form,notes:e.target.value})}/></label><footer><button type="button" className="secondary" onClick={()=>set(null)}>Cancelar</button><button data-testid="save-client" className="primary">Salvar cliente</button></footer></form></div>}
function Orders({orders,all,clients,selected,setSelected,query,setQuery,status,setStatus,late,setLate,clear,create,save,total,error,notice}:any){const o=all.find((x:Order)=>x.id===selected);return <><header><div><p>ATENDIMENTO</p><h1>Ordens de serviço</h1></div><button data-testid="btn-new-order" className="primary" onClick={create}>+ Nova ordem</button></header><div className="filters"><input data-testid="order-search" placeholder="Número ou cliente" value={query} onChange={e=>setQuery(e.target.value)}/><select data-testid="status-filter" value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos os status</option>{[...steps,'Cancelado'].map(s=><option key={s}>{s}</option>)}</select><label className="check"><input data-testid="late-filter" type="checkbox" checked={late} onChange={e=>setLate(e.target.checked)}/> Apenas atrasadas</label><button className="secondary" onClick={clear}>Limpar filtros</button></div><div className="split"><section className="panel list"><OrderTable orders={orders} client={(id:string)=>clients.find((c:Client)=>c.id===id)} total={total} open={setSelected}/>{!orders.length&&<div className="empty">Nenhuma ordem atende aos filtros.</div>}</section><section className="panel detail">{o?<OrderDetail o={o} client={clients.find((c:Client)=>c.id===o.clientId)} save={save} total={total} error={error} notice={notice}/>:<div className="empty">Selecione uma ordem para consultar orçamento e histórico.</div>}</section></div></>}
function OrderTable({orders,client,total,open}:any){return <div className="table">{orders.map((o:Order)=><button className="orderrow" key={o.id} onClick={()=>open(o.id)}><b>{o.number}</b><span>{client(o.clientId)?.name}</span><Badge s={o.status}/><strong>{money(total(o))}</strong></button>)}</div>}; function Badge({s}:any){return <em className={'badge '+s.replaceAll(' ','')}>{s}</em>}
function OrderDetail({o,client,save,total,error,notice}:any){const locked=['Em manutenção','Pronto','Entregue','Cancelado'].includes(o.status);const subtotal=o.items.reduce((a:number,i:Item)=>a+i.qty*i.unit,0);function patch(p:Partial<Order>){save((d:DB)=>({...d,orders:d.orders.map(x=>x.id===o.id?{...x,...p}:x)}))}function add(){if(locked)return;patch({items:[...o.items,{id:'i'+Date.now(),description:'Novo item',type:'Peça',qty:1,unit:0}],approvedAt:undefined})}function advance(){const ix=steps.indexOf(o.status);if(o.status==='Aguardando aprovação'&&!o.approvedAt)return error('Registre a aprovação do orçamento antes de iniciar a manutenção.');if(ix<0||ix===steps.length-1)return;const next=steps[ix+1];patch({status:next,history:[...o.history,{date:now(),from:o.status,to:next}]});notice('Status atualizado.')}return <><div className="sectionhead"><div><h2>{o.number}</h2><span>{client?.name} · {o.equipment} {o.brand} {o.model}</span></div><Badge s={o.status}/></div><p><b>Relato:</b> {o.problem}</p><label>Diagnóstico técnico<textarea disabled={locked} value={o.diagnosis} onChange={e=>patch({diagnosis:e.target.value})}/></label><label>Previsão de entrega<input type="date" disabled={locked} value={o.due} onChange={e=>patch({due:e.target.value})}/></label><h3>Orçamento {locked&&<small>bloqueado nesta etapa</small>}</h3>{o.items.map((i:Item)=><div className="budget" key={i.id}><input disabled={locked} value={i.description} onChange={e=>patch({items:o.items.map(x=>x.id===i.id?{...x,description:e.target.value}:x),approvedAt:undefined})}/><select disabled={locked} value={i.type} onChange={e=>patch({items:o.items.map(x=>x.id===i.id?{...x,type:e.target.value as any}:x),approvedAt:undefined})}><option>Peça</option><option>Serviço</option></select><input disabled={locked} type="number" min="1" value={i.qty} onChange={e=>patch({items:o.items.map(x=>x.id===i.id?{...x,qty:Math.max(1,+e.target.value)}:x),approvedAt:undefined})}/><input disabled={locked} type="number" min="0" value={(i.unit/100).toFixed(2)} onChange={e=>patch({items:o.items.map(x=>x.id===i.id?{...x,unit:Math.round(+e.target.value*100)}:x),approvedAt:undefined})}/><span>{money(i.qty*i.unit)}</span><button disabled={locked} onClick={()=>patch({items:o.items.filter(x=>x.id!==i.id),approvedAt:undefined})}>×</button></div>)}{!locked&&<button className="secondary" onClick={add}>+ Adicionar item</button>}<label>Desconto (R$)<input data-testid="discount-input" disabled={locked} type="number" min="0" value={(o.discount/100).toFixed(2)} onChange={e=>{const v=Math.round(+e.target.value*100);if(v<0||v>subtotal)return error('O desconto deve estar entre R$ 0,00 e o subtotal.');patch({discount:v,approvedAt:undefined})}}/></label><div className="totals"><span>Subtotal <b>{money(subtotal)}</b></span><span>Desconto <b>- {money(o.discount)}</b></span><strong>Total final <b data-testid="order-total">{money(total(o))}</b></strong></div><div className="actions">{o.status==='Aguardando aprovação'&&!o.approvedAt&&<button data-testid="approve-budget" className="primary" onClick={()=>{if(!o.items.length||total(o)<=0)return error('Adicione itens e um total final maior que zero para aprovar.');patch({approvedAt:now()});notice('Aprovação registrada.')}}>Registrar aprovação</button>}{!['Entregue','Cancelado'].includes(o.status)&&<><button data-testid="advance-status" className="primary" onClick={advance}>Avançar etapa</button><button className="danger" onClick={()=>patch({status:'Cancelado',history:[...o.history,{date:now(),from:o.status,to:'Cancelado'}]})}>Cancelar ordem</button></>}</div><h3>Histórico</h3>{o.history.slice().reverse().map((h:Log,i:number)=><div className="history" key={i}>{new Date(h.date).toLocaleString('pt-BR')} · {h.from||'Criada'} → <b>{h.to}</b></div>)}</>}
function OrderCreate({clients,close,submit}:any){return <div className="modal"><form className="dialog" onSubmit={submit}><h2>Nova ordem de serviço</h2><label>Cliente*<select data-testid="order-client" name="client" defaultValue=""><option value="" disabled>Selecione o cliente</option>{clients.map((c:Client)=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label>Equipamento<select name="equipment"><option>Desktop</option><option>Notebook</option><option>Outro</option></select></label><label>Marca<input name="brand"/></label><label>Modelo<input name="model"/></label><label>Problema relatado*<textarea data-testid="order-problem" name="problem"/></label><label>Previsão de entrega<input name="due" type="date" defaultValue={date(3)}/></label><footer><button type="button" className="secondary" onClick={close}>Cancelar</button><button data-testid="save-order" className="primary">Criar ordem</button></footer></form></div>}
"},{"path":"src/styles.css","content":":root{--canvas:#08090a;--surface:#101216;--elevated:#171a20;--hover:#20242c;--line:rgba(255,255,255,.09);--text:#f5f7fb;--muted:#9098a6;--blue:#6074ee;--blue2:#8190ff;--danger:#f06d77;--warn:#e8bd5d;--ok:#55c58b;--radius:8px;--shadow:0 12px 34px #0005}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--text);font:14px Inter,ui-sans-serif,system-ui,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.shell{display:flex;min-height:100vh}aside{position:sticky;top:0;width:235px;height:100vh;padding:24px 14px;border-right:1px solid var(--line);background:#0b0c0f;display:flex;flex-direction:column}.logo{font-size:18px;letter-spacing:.3px;padding:0 10px 30px}.logo b{background:var(--blue);border-radius:5px;padding:4px 5px;margin-right:5px}nav{display:grid;gap:5px}nav button{height:43px;background:transparent;border:0;color:var(--muted);text-align:left;border-radius:6px;padding:0 12px;display:flex;gap:11px;align-items:center}nav button.active,nav button:hover{color:white;background:var(--hover)}nav button.active{box-shadow:inset 2px 0 var(--blue)}aside small{margin-top:auto;color:var(--muted);line-height:1.7;padding:10px}main{width:calc(100% - 235px);padding:32px;max-width:1500px;margin:auto}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}header p{color:var(--blue2);font-size:11px;letter-spacing:1.4px;margin:0 0 7px;font-weight:bold}h1{font-size:27px;margin:0;letter-spacing:-.7px}h2{font-size:17px;margin:0}h3{font-size:14px;margin:25px 0 10px}small,.muted{color:var(--muted)}.primary,.secondary,.danger{border-radius:6px;border:1px solid var(--line);padding:9px 13px;color:var(--text);font-weight:650}.primary{border:0;background:var(--blue);box-shadow:0 0 18px #6074ee35}.primary:hover{background:var(--blue2)}.secondary{background:var(--elevated)}.danger{background:transparent;color:#ff9ba3;border-color:#74333b}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:22px}.metric,.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius)}.metric{padding:18px}.metric strong{display:block;font-size:24px;font-variant-numeric:tabular-nums}.metric span{color:var(--muted);font-size:12px}.bad{color:var(--danger)}.panel{padding:17px}.sectionhead{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.sectionhead span{color:var(--muted);font-size:12px}.orderrow,.row{width:100%;display:grid;grid-template-columns:150px 1fr 175px 105px;align-items:center;gap:10px;border:0;border-top:1px solid var(--line);background:transparent;color:var(--text);padding:13px 6px;text-align:left}.orderrow:hover,.row:hover,.row.selected{background:var(--hover)}.orderrow span,.row span{color:var(--muted)}.orderrow strong,.totals b{font-variant-numeric:tabular-nums}.badge{font-style:normal;font-size:11px;color:var(--muted)}.badge:before{content:'•';font-size:18px;vertical-align:-1px;margin-right:4px;color:var(--blue2)}.badge.Pronto:before{color:var(--ok)}.badge.Cancelado:before{color:var(--danger)}.badge.Aguardandoaprovação:before{color:var(--warn)}.split{display:grid;grid-template-columns:minmax(380px,1fr) minmax(460px,1.2fr);gap:16px}.list{padding:10px}.list>input,.filters input,.filters select{width:100%;margin-bottom:8px}.row{display:flex;flex-direction:column;align-items:flex-start}.detail{min-height:450px}.empty{color:var(--muted);padding:35px;text-align:center}.filters{display:flex;gap:9px;align-items:center;margin:-8px 0 16px}.filters input{max-width:300px}.filters select{max-width:210px}.check{white-space:nowrap;color:var(--muted)}input,select,textarea{background:#0b0d10;border:1px solid var(--line);border-radius:5px;color:var(--text);padding:9px;width:100%}textarea{min-height:67px;resize:vertical}label{display:block;font-size:12px;color:var(--muted);margin:13px 0 0}label input,label select,label textarea{margin-top:5px;color:var(--text)}.linked,.history{border-top:1px solid var(--line);padding:9px 2px;display:flex;justify-content:space-between;font-size:12px}.history{display:block;color:var(--muted)}.detail>p{line-height:1.55;color:var(--muted)}.budget{display:grid;grid-template-columns:1.4fr .8fr 58px 92px 90px 24px;gap:5px;margin:6px 0}.budget input,.budget select{padding:7px}.budget span{align-self:center;text-align:right;font-variant-numeric:tabular-nums}.budget button{background:transparent;color:var(--danger);border:0;font-size:18px}.totals{margin-top:15px;border-top:1px solid var(--line);padding-top:9px;display:grid;gap:6px;width:min(300px,100%);margin-left:auto}.totals span,.totals strong{display:flex;justify-content:space-between}.totals strong{font-size:15px}.actions{margin-top:18px;display:flex;gap:8px;flex-wrap:wrap}.modal{position:fixed;z-index:3;inset:0;background:#0009;display:grid;place-items:center;padding:18px}.dialog{width:min(520px,100%);max-height:94vh;overflow:auto;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);border-radius:10px;padding:22px}.dialog footer{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.notice,.error{position:fixed;z-index:5;right:22px;top:18px;padding:11px 14px;background:#173326;border:1px solid #367953;border-radius:6px;color:#b9f1d0}.error{background:#3a1b20;border-color:#85404a;color:#ffbdc3}.notice button,.error button{border:0;background:transparent;color:inherit;font-size:18px;margin-left:12px}.danger{margin-top:22px}.table{max-width:100%;overflow-x:auto}@media(max-width:720px){body{padding-bottom:66px}.shell{display:block}aside{z-index:2;position:fixed;bottom:0;top:auto;width:100%;height:64px;padding:5px;background:#0b0c0f;border-top:1px solid var(--line);border-right:0}aside .logo,aside small{display:none}nav{grid-template-columns:repeat(3,1fr);height:100%}nav button{justify-content:center;flex-direction:column;font-size:16px;gap:0;height:54px;padding:0}nav button span{font-size